package com.cineflow.bug.service; import static org.assertj.core.api.Assertions.assertThat; import java.nio.file.*; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.io.TempDir; import org.springframework.mock.web.MockMultipartFile; class FileStorageServiceTest { @TempDir Path root; @Test void preservesNameAndUsesUniqueFolders(){var s=new FileStorageService(root.toString());var f=new MockMultipartFile("file","C:\\tmp\\proof.png","image/png","x".getBytes());String a=s.store(f).relativePath(),b=s.store(f).relativePath();assertThat(a).endsWith("/proof.png").isNotEqualTo(b);assertThat(Files.exists(root.resolve(a))).isTrue();} }
